const toggleDarkMode = useCallback(async () => {
  if (!buttonRef.current) return;

  // Step 1: Start the view transition, apply theme inside flushSync
  await document.startViewTransition(() => {
    flushSync(() => {
      const newMode = !isDark;
      setIsDark(newMode);
      const modeValue = newMode ? "dark" : "light";
      document.documentElement.dataset.theme = modeValue;
      localStorage.setItem("theme", modeValue);
      document.cookie = `payload-theme=${modeValue};path=/;max-age=${60 * 60 * 24 * 365}`;
    });
  }).ready;

  // Step 2: Calculate the circle origin from the button's position
  const { top, left, width, height } =
    buttonRef.current.getBoundingClientRect();
  const x = left + width / 2;
  const y = top + height / 2;
  const maxRadius = Math.hypot(
    Math.max(left, window.innerWidth - left),
    Math.max(top, window.innerHeight - top),
  );

  // Step 3: Animate a clip-path circle expanding from the button
  document.documentElement.animate(
    {
      clipPath: [
        `circle(0px at ${x}px ${y}px)`,
        `circle(${maxRadius}px at ${x}px ${y}px)`,
      ],
    },
    {
      duration: 400,
      easing: "ease-in-out",
      pseudoElement: "::view-transition-new(root)",
    },
  );
}, [isDark]);

