import { cookies } from "next/headers";
import { getGoogleFontsUrl } from "@/lib/color-scheme-fonts";
import type { ColorSchemeName } from "@/components/ui/color-scheme-selector-modal";

export default async function RootLayout({ children }) {
  const cookieStore = await cookies();
  const darkMode = cookieStore.get("payload-theme")?.value;
  const colorSchemeName =
    (cookieStore.get("colorScheme")?.value as ColorSchemeName) || "graphite";
  const googleFontsUrl = getGoogleFontsUrl(colorSchemeName);

  return (
    <html
      lang="en"
      data-theme={darkMode === "dark" ? "dark" : "light"}
      suppressHydrationWarning
    >
      <head>
        {/* Preconnect to Google Fonts for faster font loading */}
        {googleFontsUrl && (
          <>
            <link rel="preconnect" href="https://fonts.googleapis.com" />
            <link rel="preconnect" href="https://fonts.gstatic.com" crossOrigin="anonymous" />
            <link rel="stylesheet" href={googleFontsUrl} />
          </>
        )}

        {/* THE KEY LINE: dynamically load the correct theme CSS */}
        <link rel="stylesheet" href={`/colorSchemes/${colorSchemeName}.css`} />
      </head>
      <body className="font-sans antialiased">
        {children}
      </body>
    </html>
  );
}

// lib/color-scheme-fonts.ts
const colorSchemeFonts: Record<ColorSchemeName, string[]> = {
  graphite: ["Montserrat", "Inter", "Fira Code"],
  cyberpunk: ["Outfit", "Fira Code"],
  notebook: ["Architects Daughter", "Fira Code"],
  "neo-brutalism": ["DM Sans", "Space Mono"],
  vercel: ["Geist", "Geist Mono"],
  // ... 38 more themes
};

export function getGoogleFontsUrl(schemeName: ColorSchemeName): string | null {
  const fontNames = colorSchemeFonts[schemeName];
  if (!fontNames || fontNames.length === 0) return null;

  const families = fontNames
    .map((name) => {
      const encoded = name.replace(/ /g, "+");
      return `family=${encoded}:wght@300..900`;
    })
    .join("&");

  return `https://fonts.googleapis.com/css2?${families}&display=swap`;
}

