function getActiveColorScheme(): ColorSchemeName {
  if (typeof document === "undefined") return "graphite";
  const match = document.cookie
    .split("; ")
    .find((row) => row.startsWith("colorScheme="));
  return (match?.split("=")[1] as ColorSchemeName) || "graphite";
}

